#include "my_hw/my_hardware.hpp"

#include <string>

#include "hardware_interface/types/hardware_interface_type_values.hpp"
#include "pluginlib/class_list_macros.hpp"
#include "rclcpp/logging.hpp"

namespace my_hw
{

hardware_interface::CallbackReturn MyHardware::on_init(
  const hardware_interface::HardwareComponentInterfaceParams & params)
{
  if (
    hardware_interface::SystemInterface::on_init(params) !=
    hardware_interface::CallbackReturn::SUCCESS)
  {
    return hardware_interface::CallbackReturn::ERROR;
  }

  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    if (
      joint.command_interfaces.size() != 1 ||
      joint.command_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' must have exactly one 'position' command interface.",
        joint.name.c_str());
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.state_interfaces.size() != 2)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' must expose 'position' and 'velocity' state interfaces.",
        joint.name.c_str());
      return hardware_interface::CallbackReturn::ERROR;
    }

    joint_names_.push_back(joint.name);
  }

  RCLCPP_INFO(get_logger(), "MyHardware initialized with %zu joints.", joint_names_.size());

  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::return_type MyHardware::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  // No physical hardware to poll: the state is updated directly in write()
  // by integrating the last commanded position, so there is nothing to do here.
  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MyHardware::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const double dt = period.seconds();

  for (const auto & joint_name : joint_names_)
  {
    const std::string position_interface =
      joint_name + "/" + hardware_interface::HW_IF_POSITION;
    const std::string velocity_interface =
      joint_name + "/" + hardware_interface::HW_IF_VELOCITY;

    const double commanded_position = get_command<double>(position_interface);
    const double previous_position = get_state<double>(position_interface);
    const double velocity = dt > 0.0 ? (commanded_position - previous_position) / dt : 0.0;

    set_state<double>(position_interface, commanded_position);
    set_state<double>(velocity_interface, velocity);
  }

  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

PLUGINLIB_EXPORT_CLASS(my_hw::MyHardware, hardware_interface::SystemInterface)

